    const long long values[] = {0, 1, 2, 3, 10, 1000, max / 2, max / 2 + 1, max - 1, max};
    for (int attempt = 0; attempt <= 60; ++attempt) {
        for (long long base : values) {
            for (long long cap : values) {
                const __int128 product = static_cast<__int128>(base) << attempt;
                const long long expected = product > cap ? cap : static_cast<long long>(product);
                assert(retry_delay(attempt, base, cap) == expected);
            }
        }
    }
}
